test('실제 HUMAN 원명령과 receipt 감사→writer RESERVED→권위2표 재조회가 같은 메모리 Tx에서 연결된다',async()=>{const f=await nativeFixture();try{const before=f.data(),url=`/api/v1/projects/${f.pid}/native-boundary-preparations`,response=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(response.statusCode,200,response.body+f.sideband());const v=response.json();assert.equal(v.data.status,'NATIVE_BOUNDARY_PREPARATION_RECORDED');const s=f.data();assert.equal(s.commands.length,before.commands.length+1);assert.equal(s.native.length,1);assert.equal(s.nativeEvents.length,1);assert.equal(s.heads[0].phase,'RESERVED');assert.notEqual(s.native[0].server_command_id,f.nativeCommand.commandId);const fixed=await f.nativeApp.inject({method:'GET',url:url+'/'+v.data.ref.id,headers:f.headers});assert.equal(fixed.statusCode,200,fixed.body);assert.deepEqual(fixed.json().preparationIntent,v.data.preparationIntent);const replay=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(replay.statusCode,200,replay.body);assert.deepEqual(replay.json(),v);assert.deepEqual(f.data(),s);}finally{await f.close();}});

test('두 표 INSERT 중간 실패와 old head CAS 실패는 원명령 receipt 감사와 reserve를 함께 rollback한다',async()=>{for(const mode of['EVENT','HEAD']){const f=await nativeFixture();try{const before=f.data();if(mode==='HEAD')f.failHead();else{const query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(sql.startsWith('INSERT INTO anvil.native_preparation_authority_events'))throw Error('SYNTHETIC_NATIVE_WRITE_FAILED');return query(sql,args);};}const r=await f.nativeApp.inject({method:'POST',url:`/api/v1/projects/${f.pid}/native-boundary-preparations`,headers:f.headers,payload:f.nativeCommand});assert.equal(r.statusCode,503,r.body);assert.deepEqual(f.data(),before);}finally{await f.close();}}});
test('COMMIT 불명은 원결과만 보존하고 명시 replay는 재예약 재발급하지 않는다',async()=>{const f=await nativeFixture();try{f.loseCommit();const url=`/api/v1/projects/${f.pid}/native-boundary-preparations`;const r=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(r.statusCode,503);const committed=f.data();assert.equal(committed.native.length,1);const again=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(again.statusCode,200,again.body);assert.deepEqual(f.data(),committed);}finally{await f.close();}});
