test('round1 I4 options supplier await 동안 session 또는 readpolicy 기한이 지나면 반환하지 않는다',async()=>{for(const mode of['SESSION','POLICY']){const f=await nativeFixture();try{const expires=new Date(f.clockDate().getTime()+500).toISOString();if(mode==='SESSION')f.actor.authSession.idleExpiresAt=expires;else{const query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{const result=await query(sql,args);if(sql.includes('FROM anvil.permission_policies p JOIN anvil.permission_policy_versions')){const row:any=result.rows[0];row.rules_json=row.rules_json.map((r:any)=>({...r,expiresAt:expires}));row.content_hash=writerHash({rules:row.rules_json,reason:row.reason,reviewRefs:row.review_refs});}return result;};}f.onOptions(()=>f.advanceClock(1000));const r=await f.nativeApp.inject({method:'GET',url:`/api/v1/projects/${f.pid}/native-boundary-preparation-options`,headers:f.headers});assert.equal(r.statusCode,412,mode+r.body);assert.equal(r.json().code,'NATIVE_SOURCE_EXPIRED');}finally{await f.close();}}});
