test('round1 I5 원승인과 grant 기한 만료 뒤 역사와 원명령 replay는 새 권위를 생성하지 않는다',async()=>{const f=await nativeFixture(true);try{const url=`/api/v1/projects/${f.pid}/native-boundary-preparations`,r=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(r.statusCode,200,r.body+f.sideband());const before=f.data();f.advanceClock(120000);const fixed=await f.nativeApp.inject({method:'GET',url:url+'/'+r.json().data.ref.id,headers:f.headers});assert.equal(fixed.statusCode,200,fixed.body);assert.equal(fixed.json().currentStatus,'EXPIRED');assert.deepEqual(fixed.json().preparationIntent,r.json().data.preparationIntent);const repeated=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(repeated.statusCode,200,repeated.body);assert.deepEqual(repeated.json(),r.json());assert.deepEqual(f.data(),before);}finally{await f.close();}});

test('round2 options deadline 뒤 release된 raw client로 late supplier query가 도달하지 않는다',async t=>{const f=await nativeFixture();let resume!:()=>void,lateQueries=0,releases=0;const query=f.db.query.bind(f.db),access=f.service.access as any,authenticated=access.authenticated.bind(access);f.db.query=async(sql:string,args:any[]=[])=>{if(sql==='SELECT LATE_OPTIONS_QUERY'){lateQueries++;return{rows:[]};}return query(sql,args);};access.authenticated=async(token:string,csrf:string|null,body:any)=>{try{return await authenticated(token,csrf,body);}finally{releases++;}};f.onOptions(async db=>{await new Promise<void>(r=>{resume=r;});try{await db.query('SELECT LATE_OPTIONS_QUERY');}catch{}});try{t.mock.timers.enable({apis:['setTimeout']});const pending=f.nativeApp.inject({method:'GET',url:`/api/v1/projects/${f.pid}/native-boundary-preparation-options`,headers:f.headers});while(!resume)await new Promise(r=>setImmediate(r));t.mock.timers.tick(10000);const result=await pending;assert.equal(result.statusCode,412,result.body);assert.equal(releases,1);assert.equal(f.service.pendingOptionsSuppliers,1,'미정착 supplier를 종료완료로 표시하지 않음');resume();await new Promise(r=>setImmediate(r));assert.equal(f.service.pendingOptionsSuppliers,0);assert.equal(lateQueries,0,'원 client에 만료 뒤 추가 query0');}finally{t.mock.timers.reset();if(resume)resume();await f.close();}});

test('round2 이미 진행중인 query는 정착까지 lease를 유지하고 late 정상도 COMMIT하지 않는다',async()=>{const f=await nativeFixture(false,30);let resolveQuery!:(v:any)=>void,releases=0,commits=0,rollbacks=0,late=0,unhandled=0;const before=f.data(),query=f.db.query.bind(f.db),access=f.service.access as any,authenticated=access.authenticated.bind(access),onUnhandled=()=>{unhandled++;};process.on('unhandledRejection',onUnhandled);f.db.query=async(sql:string,args:any[]=[])=>{if(sql==='SELECT HOLD_OPTIONS_QUERY')return new Promise(r=>{resolveQuery=r;});if(sql==='SELECT LATE_OPTIONS_QUERY'){late++;return{rows:[]};}return query(sql,args);};access.authenticated=async(token:string,csrf:string|null,body:any)=>{try{return await authenticated(token,csrf,async(db:any,actor:any)=>{try{const result=await body(db,actor);commits++;return result;}catch(error){rollbacks++;throw error;}});}finally{releases++;}};f.onOptions(async db=>{assert.deepEqual(Object.keys(db),['query']);assert.equal((db as {release?:unknown}).release,undefined);try{await db.query('SELECT HOLD_OPTIONS_QUERY');}finally{try{await db.query('SELECT LATE_OPTIONS_QUERY');}catch{}throw Error('SYNTHETIC_RAW_SECRET_LATE');}});try{const r=await f.nativeApp.inject({method:'GET',url:`/api/v1/projects/${f.pid}/native-boundary-preparation-options`,headers:f.headers});assert.equal(r.statusCode,412,r.body);assert(resolveQuery);assert.equal(releases,0,'진행중 query의 lease 반환0');assert.equal(f.service.pendingOptionsTransactions,1);assert.equal(commits,0);assert(!r.body.includes('RAW_SECRET'));resolveQuery({rows:[]});for(let i=0;i<100&&f.service.pendingOptionsTransactions;i++)await new Promise(r=>setImmediate(r));await new Promise(r=>setImmediate(r));assert.equal(f.service.pendingOptionsTransactions,0);assert.equal(f.service.pendingOptionsSuppliers,0);assert.equal(releases,1);assert.equal(rollbacks,1);assert.equal(commits,0);assert.equal(late,0);assert.equal(unhandled,0);assert.deepEqual(f.data(),before);}finally{process.off('unhandledRejection',onUnhandled);if(resolveQuery)resolveQuery({rows:[]});await f.close();}});
test('round2 짧은 options 예산은 내부에서만 주입하며 1..10000 범위 밖은 거절한다',async()=>{const f=await nativeFixture();try{for(const timeoutMs of[0,10001,Infinity,NaN,1.5])assert.throws(()=>new ProjectNativePreparations(f.service.access,f.persistence,f.nativeSource,undefined,{timeoutMs}));}finally{await f.close();}});

test('round2 정상 options는 기존 정확 응답과 현재 read 최소기한을 유지한다',async()=>{const f=await nativeFixture();try{const r=await f.nativeApp.inject({method:'GET',url:`/api/v1/projects/${f.pid}/native-boundary-preparation-options`,headers:f.headers});assert.equal(r.statusCode,200,r.body);const v=r.json();assert.deepEqual(Object.keys(v).sort(),['schemaVersion','projectId','writerHead','items','observedAt','expiresAt','codingAgentExecutionAuthorized','agentDispatchPerformed'].sort());assert.equal(v.projectId,f.pid);assert.equal(v.writerHead.snapshot.phase,'EMPTY_AT');assert.equal(v.items.length,1);assert.equal(v.codingAgentExecutionAuthorized,false);assert.equal(v.agentDispatchPerformed,false);assert.equal(f.service.pendingOptionsTransactions,0);assert.equal(f.service.pendingOptionsSuppliers,0);}finally{await f.close();}});

test('HUMAN 고정 조회는 유효 로그인 뒤 읽기 정책 미설정 미일치와 타 프로젝트를 404로 은폐한다',async()=>{for(const mode of['MISSING','DENY','OTHER_PROJECT']){const f=await nativeFixture();try{const query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(mode==='OTHER_PROJECT'&&sql.includes('FROM anvil.projects p JOIN anvil.project_members'))return{rows:[]};if(sql.includes('FROM anvil.permission_policies p JOIN anvil.permission_policy_versions')){if(mode==='MISSING')return{rows:[]};const value=await query(sql,args),row=value.rows[0];row.rules_json=row.rules_json.map((rule:any)=>({...rule,operations:rule.operations.filter((op:string)=>op!=='readNativePreparationAuthority')}));row.content_hash=writerHash({rules:row.rules_json,reason:row.reason,reviewRefs:row.review_refs});return value;}return query(sql,args);};const r=await f.nativeApp.inject({url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations/'+id(9000),headers:f.headers});assert.equal(r.statusCode,404,mode+':'+r.body);assert.deepEqual(r.json(),{code:'NATIVE_AUTHORITY_NOT_FOUND',requestId:null});}finally{await f.close();}}});

test('B 서버는 실제 HUMAN 생산 권위와 등록 세션을 읽고 current와 challenge 원문을 저장 재조회한다',async()=>{const f=await nativeFixture(false,10000,true);try{const prepared=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(prepared.statusCode,200,prepared.body+f.sideband());const row=f.data().native[0],authorityRef={id:row.id,version:1,contentHash:row.content_hash},headers={host:new URL(f.origin).host,authorization:'Bearer '+testOpaque},base='/api/v1/connector/native-preparations/'+row.id;const current=await f.nativeApp.inject({url:base+'/current',headers});assert.equal(current.statusCode,200,current.body);assert.equal(current.json().phase,'RESERVED');assert.equal(current.json().codingAgentExecutionAuthorized,false);const body={schemaVersion:1,authorityRef,localAttemptRef:ref(6000)},request={...body,requestId:id(6001),target:{method:'POST',path:base+'/consume',queryHash:writerHash({}),bodyHash:writerHash(body)}};const first=await f.nativeApp.inject({method:'POST',url:base+'/challenges',headers,payload:request});assert.equal(first.statusCode,200,first.body);assert.equal(f.data().nativeEvents.length,2);const again=await f.nativeApp.inject({method:'POST',url:base+'/challenges',headers,payload:request});assert.equal(again.statusCode,200,again.body);assert.deepEqual(again.json(),first.json());assert.equal(f.data().nativeEvents.length,2);const conflict=await f.nativeApp.inject({method:'POST',url:base+'/challenges',headers,payload:{...request,requestId:id(6002)}});assert.equal(conflict.statusCode,409,conflict.body);assert.equal(f.data().nativeEvents.length,2);}finally{await f.close();}});

async function hostFixture(){const f=await nativeFixture(false,10000,true),prepared=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(prepared.statusCode,200,prepared.body+f.sideband());const row=f.data().native[0],authorityRef={id:row.id,version:1,contentHash:row.content_hash},headers={host:new URL(f.origin).host,authorization:'Bearer '+testOpaque},path='/api/v1/connector/native-preparations/'+row.id,body={schemaVersion:1,authorityRef,localAttemptRef:ref(6000)},request={...body,requestId:id(6001),target:{method:'POST',path:path+'/consume',queryHash:writerHash({}),bodyHash:writerHash(body)}};const challenge=await f.nativeApp.inject({method:'POST',url:path+'/challenges',headers,payload:request});assert.equal(challenge.statusCode,200,challenge.body);const proof={requestId:request.requestId,...request.target,authorityRef,credentialGeneration:1,serverNonce:challenge.json().serverNonce},signature=sign('sha256',nativeRequestProofBytes(proof),{key:testPrivateKey,dsaEncoding:'ieee-p1363'}).toString('base64url'),proofHeaders={...headers,'x-anvil-native-proof':Buffer.from(canonicalJson(proof)).toString('base64url'),'x-anvil-native-signature':signature};return{...f,humanHeaders:f.headers,headers,proofHeaders,path,body,proof};}
test('B RFC 공개 시험키의 새 도메인 서명→실제 consume 원자 저장과 replay null permit을 연결한다',async()=>{const f=await hostFixture();try{const first=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:f.proofHeaders,payload:f.body});assert.equal(first.statusCode,200,first.body);assert.equal(first.json().disposition,'FIRST_COMMIT');assert.equal(first.json().factoryPermit.snapshot.consumeRecordRef.contentHash,first.json().recordRef.contentHash);assert.equal(f.data().nativeEvents.length,4);const replay=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:f.proofHeaders,payload:f.body});assert.equal(replay.statusCode,200,replay.body);assert.deepEqual(replay.json(),{receipt:first.json().receipt,recordRef:first.json().recordRef,disposition:'REPLAY_ONLY',factoryPermit:null});assert.equal(f.data().nativeEvents.length,4);assert(f.calls.lastIndexOf('COMMIT')>f.calls.lastIndexOf('INSERT INTO anvil.native_preparation_authority_events'));}finally{await f.close();}});
test('B 서명 다른 목적 nonce body 변경은 consume 사건을 만들지 않는다',async()=>{const f=await hostFixture();try{const before=f.data();const wrongSignature=sign('sha256',Buffer.from(canonicalJson({purpose:'EXECUTION_REQUEST_PROOF',request:f.proof})),{key:testPrivateKey,dsaEncoding:'ieee-p1363'}).toString('base64url');const domain=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:{...f.proofHeaders,'x-anvil-native-signature':wrongSignature},payload:f.body});assert.equal(domain.statusCode,403,domain.body);const alteredProof={...f.proof,serverNonce:'B'.repeat(42)+'A'},nonce=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:{...f.proofHeaders,'x-anvil-native-proof':Buffer.from(canonicalJson(alteredProof)).toString('base64url')},payload:f.body});assert.equal(nonce.statusCode,409,nonce.body);const body=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:f.proofHeaders,payload:{...f.body,localAttemptRef:ref(6999)}});assert.equal(body.statusCode,409,body.body);assert.deepEqual(f.data(),before);}finally{await f.close();}});
test('B consume 중간 INSERT 실패는 rollback하고 COMMIT 불명 뒤 원 재확인은 새 permit을 주지 않는다',async()=>{for(const mode of['INSERT','COMMIT']){const f=await hostFixture();try{const before=f.data(),query=f.db.query.bind(f.db);if(mode==='INSERT')f.db.query=async(sql:string,args:any[]=[])=>{if(sql.startsWith('INSERT INTO anvil.native_preparation_authority_events')&&JSON.parse(args[6]).kind==='CONSUME_COMMITTED')throw Error('SYNTHETIC_WRITE_UNKNOWN');return query(sql,args);};else f.loseCommit();const r=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:f.proofHeaders,payload:f.body});assert.equal(r.statusCode,503,r.body);if(mode==='INSERT')assert.deepEqual(f.data(),before);else{assert.equal(r.json().code,'NATIVE_OUTCOME_UNKNOWN');const again=await f.nativeApp.inject({method:'POST',url:f.path+'/consume',headers:f.proofHeaders,payload:f.body});assert.equal(again.statusCode,200,again.body);assert.equal(again.json().disposition,'REPLAY_ONLY');assert.equal(again.json().factoryPermit,null);}}finally{await f.close();}}});

test('B issuer의 보호 비밀은 별도 인자로 전달하고 ATTEMPTED commit 뒤 최대 한 번만 호출한다',async()=>{const f=await nativeFixture(false,10000,true,true);try{const response=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(response.statusCode,200,response.body+f.sideband());assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);assert.deepEqual(f.data().nativeEvents.map(e=>e.snapshot_json.kind),['AUTHORITY_CREATED','DELIVERY_ATTEMPTED','DELIVERY_CONFIRMED']);assert(!JSON.stringify(f.data()).includes(testOpaque));const again=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(again.statusCode,200,again.body);assert.deepEqual(again.json(),response.json());assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);}finally{await f.close();}});

test('B 실제 서버와 connector를 같은 원 tuple로 연결해 첫 factory1과 명시 재시도 추가0을 검산한다',async()=>{const f=await nativeFixture(false,10000,true);try{const response=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(response.statusCode,200,response.body);const row=f.data().native[0],authority={ref:{id:row.id,version:1,contentHash:row.content_hash},snapshot:row.snapshot_json},path='/api/v1/connector/native-preparations/'+row.id,headers={host:new URL(f.origin).host,authorization:'Bearer '+testOpaque},failures:string[]=[];let effects=0,next=9000,locked=false;const records:NativeLocalRecord[]=[];
 const invoke=async(method:'GET'|'POST',suffix:string,payload?:unknown,extra:Record<string,string>={})=>{const result=await f.nativeApp.inject({method,url:path+suffix,headers:{...headers,...extra},...(payload===undefined?{}:{payload:payload as Record<string,unknown>})});if(result.statusCode!==200){failures.push(suffix+':'+result.statusCode+':'+result.json().code);throw Error('TEST_SERVER_REJECTED');}return result.json();},channel:NativeOwnedChannel={transport:'SOURCE_ONLY_MODEL',identity:{origin:f.origin,channelProfileRef:ref(46),registrationRef:f.config.registrationRef,credentialPurpose:'NATIVE_PREPARATION_ONLY',credentialGeneration:1},current:async()=>invoke('GET','/current'),challenge:async request=>invoke('POST','/challenges',request),sign:async bytes=>sign('sha256',bytes,{key:testPrivateKey,dsaEncoding:'ieee-p1363'}).toString('base64url'),consume:async(body,proof,signature)=>invoke('POST','/consume',body,{'x-anvil-native-proof':Buffer.from(canonicalJson(proof)).toString('base64url'),'x-anvil-native-signature':signature})},journal:NativeLocalJournal={transport:'SOURCE_ONLY_MODEL',exclusive:async(_ref,body)=>{if(locked)throw Error('TEST_JOURNAL_BUSY');locked=true;try{return await body({read:async()=>({complete:true,records:structuredClone(records)}),appendAndSync:async record=>{records.push(structuredClone(record));}});}finally{locked=false;}}},client=new NativePreparationClient(channel,journal,{transport:'SOURCE_ONLY_MODEL',ref:authority.snapshot.scope.nativeFactoryRef,invoke:async ticket=>{await ticket.consume();effects++;return{state:'CREATED_OBSERVED'};}},{wall:()=>f.clockDate().getTime(),monotonic:()=>performance.now(),allocate:()=>id(next++)});
 const first=await client.run(authority,id(9900));assert.equal(first.state,'CREATED_OBSERVED',JSON.stringify({first,failures}));assert.equal(effects,1);assert.deepEqual(records.map(r=>r.snapshot.state),['PREPARED','FACTORY_ATTEMPTED']);const consumed=f.data().nativeEvents.filter(e=>e.snapshot_json.kind==='CONSUME_COMMITTED').length;assert.equal(consumed,1);const again=await client.run(authority,id(9900));assert.equal(again.state,'UNKNOWN');assert.equal(effects,1);assert.equal(f.data().nativeEvents.filter(e=>e.snapshot_json.kind==='CONSUME_COMMITTED').length,1);}finally{await f.close();}});

test('B host 응답 기한은 pending query lease를 조기 반환하지 않고 늦은 정상 결과를 rollback한다',async()=>{const f=await nativeFixture(false,10000,true);let release!:()=>void;let pending:Promise<unknown>|undefined;try{const prepared=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(prepared.statusCode,200,prepared.body);const service=new ProjectNativePreparations(f.service.access,f.persistence,f.nativeSource,undefined,{timeoutMs:20},{transport:'SOURCE_ONLY_MODEL',origin:f.origin,channelProfileRef:ref(46),nonce:()=>'A'.repeat(43)}),row=f.data().native[0],query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(sql.startsWith('SELECT * FROM anvil.project_writer_authority_heads'))await new Promise<void>(r=>{release=r;});return query(sql,args);};const beforeRelease=f.calls.filter(s=>s==='RELEASE').length,beforeCommit=f.calls.filter(s=>s==='COMMIT').length;pending=service.hostCurrent(testOpaque,row.id,new URL(f.origin).host).then(()=>({state:'SUCCESS'}),error=>({state:error.message}));const result=await Promise.race([pending,new Promise(resolve=>setTimeout(()=>resolve({state:'STILL_PENDING'}),80))]);assert.notDeepEqual(result,{state:'STILL_PENDING'});assert(release);assert.equal(f.calls.filter(s=>s==='RELEASE').length,beforeRelease);release();for(let i=0;i<100&&f.calls.filter(s=>s==='RELEASE').length===beforeRelease;i++)await new Promise(r=>setImmediate(r));assert.equal(f.calls.filter(s=>s==='RELEASE').length,beforeRelease+1);assert.equal(f.calls.filter(s=>s==='COMMIT').length,beforeCommit);assert.equal(f.calls.at(-2),'ROLLBACK');}finally{release?.();await pending;await f.close();}});

test('B delivery 응답 유실은 UNCONFIRMED 원결과로 보존하고 명시 원명령 재조회도 재전달하지 않는다',async()=>{const f=await nativeFixture(false,10000,true,'LOST');try{const url='/api/v1/projects/'+f.pid+'/native-boundary-preparations',first=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(first.statusCode,200,first.body);assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);const fixed=await f.nativeApp.inject({url:url+'/'+first.json().data.ref.id,headers:f.headers});assert.equal(fixed.statusCode,200,fixed.body);assert.equal(fixed.json().currentStatus,'DELIVERY_UNCONFIRMED');assert.equal(f.data().nativeEvents.at(-1).snapshot_json.kind,'DELIVERY_UNCONFIRMED');const again=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.deepEqual(again.json(),first.json());assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);assert(!JSON.stringify(f.data()).includes(testOpaque));}finally{await f.close();}});

test('B COMMIT 대기 중 최단 current 기한이 지나면 정상 current 응답을 반환하지 않는다',async()=>{const f=await nativeFixture(false,10000,true);try{const prepared=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(prepared.statusCode,200,prepared.body);const expiry=new Date(f.clockDate().getTime()+60).toISOString(),original=f.nativeSource.current,source={...f.nativeSource,current:async(...args:Parameters<typeof original>)=>({...await original(...args),expiresAt:expiry})},service=new ProjectNativePreparations(f.service.access,f.persistence,source,undefined,{timeoutMs:10000},{transport:'SOURCE_ONLY_MODEL',origin:f.origin,channelProfileRef:ref(46),nonce:()=>'A'.repeat(43)}),query=f.db.query.bind(f.db);f.db.query=async(sql:string,args:any[]=[])=>{if(sql==='COMMIT')await new Promise(r=>setTimeout(r,90));return query(sql,args);};await assert.rejects(()=>service.hostCurrent(testOpaque,f.data().native[0].id,new URL(f.origin).host),{message:'NATIVE_OUTCOME_UNKNOWN'});}finally{await f.close();}});

test('B delivery timeout은 ATTEMPTED를 보존하며 늦은 정상 응답과 원 replay에서 재전달하지 않는다',async()=>{const f=await nativeFixture(false,80,true,'HOLD');await f.nativeApp.ready();const unhandled:unknown[]=[],onUnhandled=(error:unknown)=>unhandled.push(error);process.on('unhandledRejection',onUnhandled);const nativePerformance=performance,originalTimeout=setTimeout,originalClear=clearTimeout,performanceDescriptor=Object.getOwnPropertyDescriptor(globalThis,'performance'),timeoutDescriptor=Object.getOwnPropertyDescriptor(globalThis,'setTimeout'),clearDescriptor=Object.getOwnPropertyDescriptor(globalThis,'clearTimeout');let mono=nativePerformance.now();const scheduled=new Map<object,{at:number;run:()=>void}>();Object.defineProperty(globalThis,'performance',{configurable:true,value:new Proxy(nativePerformance,{get(target,key){if(key==='now')return()=>mono;const value=Reflect.get(target,key,target);return typeof value==='function'?value.bind(target):value;}})});Object.defineProperty(globalThis,'setTimeout',{configurable:true,value:(fn:()=>void,delay:number,...args:unknown[])=>{if(delay>0&&delay<=80){const ticket={};scheduled.set(ticket,{at:mono+delay,run:()=>Reflect.apply(fn,undefined,args)});return ticket;}return originalTimeout(fn,delay,...args);}});Object.defineProperty(globalThis,'clearTimeout',{configurable:true,value:(ticket:any)=>{if(!scheduled.delete(ticket))originalClear(ticket);}});const expire=()=>{mono+=81;for(const[ticket,timer]of [...scheduled])if(timer.at<=mono){scheduled.delete(ticket);timer.run();}};let pending:Promise<{statusCode:number;body:string}>|undefined;try{const url='/api/v1/projects/'+f.pid+'/native-boundary-preparations';pending=f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});for(let i=0;i<1000&&!f.deliveryState.release;i++)await new Promise(r=>setImmediate(r));assert(f.deliveryState.release,'전달 공급자 진입 후에만 원 80ms 예산 만료');assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);expire();const response=await pending!;assert.equal(response.statusCode,503,response.body);assert.equal(f.data().nativeEvents.at(-1).snapshot_json.kind,'DELIVERY_ATTEMPTED');const before=f.data();f.deliveryState.release!();for(let i=0;i<8;i++)await new Promise(r=>setImmediate(r));assert.deepEqual(f.data(),before);assert(f.deliveryState.opaque?.every(v=>v===0),'정착 뒤 소유 비밀 사본 폐기');const again=await f.nativeApp.inject({method:'POST',url,headers:f.headers,payload:f.nativeCommand});assert.equal(again.statusCode,200,again.body);assert.equal(f.calls.filter(v=>v==='DELIVERY_PORT').length,1);assert.equal(unhandled.length,0);}finally{expire();f.deliveryState.release?.();await pending;for(const[key,descriptor]of [['performance',performanceDescriptor],['setTimeout',timeoutDescriptor],['clearTimeout',clearDescriptor]] as const)if(descriptor)Object.defineProperty(globalThis,key,descriptor);process.off('unhandledRejection',onUnhandled);await f.close();}});

