for(const mode of ['delivery-waiter-short-e','delivery-waiter-fence','delivery-waiter-supply-throw','delivery-waiter-expired','delivery-waiter-actor'])test('원 selected waiter 경계 '+mode,()=>nativeBindingJourney([mode]));


test('ARM Binding은 실제 broker 통로 소유권이 없으면 저장의 streamOwned 선언만으로 N 선예약을 시작하지 않는다',async()=>{
 const f=await nativeFixture(false,10000,true,false,true);try{const view=await nativeBindingAdmissionFixture(f),query=f.db.query.bind(f.db);let reserves=0;f.db.query=async(sql:string,args:any[]=[])=>{if(sql==='SELECT txid_current()::text AS transaction_id')return{rows:[{transaction_id:'123'}],rowCount:1};if(sql==='SELECT anvil.native_receive_binding_admission($1,$2,$3::jsonb,$4::jsonb) AS result')return{rows:[{result:view}],rowCount:1};if(sql.startsWith('SELECT anvil.native_receive_binding_reserve')){reserves++;throw Error('금지된 선예약 진입');}return query(sql,args);};const out=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:{...f.headers,'X-Anvil-Native-Receive-Arm':Buffer.from(canonicalJson(view.arm.ref)).toString('base64url')},payload:f.nativeCommand});assert.equal(out.statusCode,503);assert.equal(reserves,0,'실제 통로가 없으면 선예약·명령·N 효과 전에 거절');assert.equal(f.data().native.length,0);
 }finally{await f.close();}
});


