test('원 command는 미관측 raw query 실패 뒤 정상 COMMIT을 차단하고 관측된 명확 거절은 덮어쓰지 않는다',async()=>{
 for(const mode of ['unobserved','observed']){const f=await nativeFixture(),query=f.db.query.bind(f.db),before=f.data(),offset=f.calls.length;let failures=0;f.db.query=async(sql:string,args:any[]=[])=>{if(sql==='SELECT fn06_unobserved_failure'){failures++;throw Object.assign(Error('합성 보호 SQL 거절'),{code:'42501'});}return query(sql,args);};f.onOptions(async(db:any)=>{if(mode==='unobserved'){void db.query('SELECT fn06_unobserved_failure').catch(()=>{});return;}try{await db.query('SELECT fn06_unobserved_failure');}catch{throw new AuthFailure('NATIVE_PURPOSE_DENIED',403);}});try{const response=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(response.statusCode,mode==='unobserved'?503:403,response.body);assert.equal(response.json().code,mode==='unobserved'?'NATIVE_OUTCOME_UNKNOWN':'NATIVE_PURPOSE_DENIED');assert.ok(failures>=1);assert.deepEqual(f.data(),before);assert.equal(f.calls.slice(offset).filter(q=>q==='COMMIT').length,0,'callback 실패 뒤 COMMIT/공급0');}finally{await f.close();}}
});


test('원 command의 non-async raw query 동기 throw는 미관측이어도 COMMIT·공급0이며 관측된403은 보존한다',async()=>{
 for(const mode of ['unobserved-sync','observed-sync']){const f=await nativeFixture(),query=f.db.query.bind(f.db),before=f.data(),offset=f.calls.length;let throws=0;const failure=Object.assign(Error('합성 동기 SQL 거절'),{code:'42501'});
  // 이 wrapper는 async 함수나 Promise.reject가 아니라 Reflect.apply 호출 중 동기로 throw한다.
  f.db.query=(sql:string,args:any[]=[])=>{if(sql==='SELECT fn06_synchronous_failure'){throws++;throw failure;}return query(sql,args);};
  f.onOptions(async(db:any)=>{if(mode==='unobserved-sync'){const rejected=db.query('SELECT fn06_synchronous_failure');assert.ok(rejected instanceof Promise);void rejected.catch(()=>{});return;}try{await db.query('SELECT fn06_synchronous_failure');}catch(error){assert.equal(error,failure);throw new AuthFailure('NATIVE_PURPOSE_DENIED',403);}});
  try{const response=await f.nativeApp.inject({method:'POST',url:'/api/v1/projects/'+f.pid+'/native-boundary-preparations',headers:f.headers,payload:f.nativeCommand});assert.equal(response.statusCode,mode==='unobserved-sync'?503:403,'동기 raw query 실패를 정상 명령으로 반환하지 않는다');assert.equal(response.json().code,mode==='unobserved-sync'?'NATIVE_OUTCOME_UNKNOWN':'NATIVE_PURPOSE_DENIED');assert.ok(throws>=1);assert.deepEqual(f.data(),before);assert.equal(f.calls.slice(offset).filter(q=>q==='COMMIT').length,0);assert.equal(f.calls.slice(offset).includes('DELIVERY_PORT'),false);/* 메모리 authenticated의 data/approval snapshot rollback은 위 deepEqual로 검산한다. */}finally{await f.close();}
 }
});
